const raw = $input.first().json;
const body = raw.body ?? raw;
const monitor = body.monitor ?? {};
const heartbeat = body.heartbeat ?? {};
const name = monitor.name || body.monitorName || 'Bilinmeyen servis';
const up = heartbeat.status === 1;
const msg = heartbeat.msg || body.msg || '';
const now = new Date().toLocaleString('tr-TR', { timeZone: 'Europe/Istanbul', day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit' });
const title = up ? '✅ Pi Gateway · İzleme' : '⚠️ Pi Gateway · İzleme';
const headline = up ? 'Servis tekrar ayakta.' : 'Servis düştü.';
const panel = '__PANEL_PROTOCOL__://status.__LAN_DOMAIN__';
let text = `${title}\n${now}\n\n${headline}\n\nServis: ${name}`;
if (msg) text += `\nDetay: ${msg}`;
text += `\n\nNe yapmalı?\n• Panel: ${panel}`;
return [{ json: { text } }];
